const mopar={label:"Mopar vehicle information",url:"https://vehicleinfo.mopar.com/",note:"Official owner manuals and model-year warning, fluid, engine and operating information"};
const service={label:"Stellantis/Mopar service information",url:"https://www.mopar.com/en-us/my-vehicle/vehicle-information.html",note:"Factory VIN-, platform-, engine-sales-code and calibration-specific service information"};
const p0520={label:"Chrysler Bulletin 18-034-14 Rev. A — revised oil-pressure sensor",url:"https://static.nhtsa.gov/odi/tsbs/2014/SB-10063326-0335.pdf",note:"Covers listed 2013–2014 vehicles including Charger and Town & Country, subject to engine, build-date and VIN/RRT applicability"};
const earlyP06dd={label:"FCA Bulletin 18-085-15 — early 3.6L powertrain software",url:"https://static.nhtsa.gov/odi/tsbs/2015/MC-10159927-9999.pdf",note:"Lists 2011–2012 LD Charger and early-build 2011 RT Town & Country 3.6L branches and includes P06DD among the addressed codes"};
const pentastarHead={label:"Chrysler Bulletin 09-002-14 Rev. B — X56 cylinder-head extension",url:"https://static.nhtsa.gov/odi/tsbs/2014/MC-10229899-9999.pdf",note:"For listed 2011–2013 3.6L vehicles, including LD Charger and RT Town & Country; applies to P0300/P0302/P0304/P0306 with leakage-test criteria"};
const chargerFlash={label:"FCA Bulletin 18-084-16 — 2013–2015 Charger 5.7L PCM update",url:"https://static.nhtsa.gov/odi/tsbs/2016/MC-10121676-9999.pdf",note:"Applies to specified LD Charger 5.7L applications and includes P0456 and P0300 among listed diagnostic improvements"};
const town2012Flash={label:"Chrysler Bulletin 18-104-15 — 2012 RT 3.6L PCM update",url:"https://static.nhtsa.gov/odi/tsbs/2015/SB-10074965-5290.pdf",note:"Applies to 2012 Town & Country/Grand Caravan 3.6L with DG2 transmission and lists P0420, P0430 and P0300–P0306"};
const townColdMisfire={label:"FCA Bulletin 18-085-16 — 2015–2016 RT 3.6L PCM update",url:"https://static.nhtsa.gov/odi/tsbs/2016/MC-10121690-9999.pdf",note:"Applies through the stated June 20, 2016 build cutoff; includes a 2015 cold-idle P0300 software branch"};

const charger={name:"Dodge Charger",kicker:"DODGE CHARGER · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Dodge Charger",about:"Dodge Charger powertrain and emissions diagnostics",yearsIntro:"Modern Charger diagnostics span LX and LD rear-wheel-drive platforms, optional AWD and 2.7L, 3.5L, 3.6L Pentastar, 5.7L HEMI, 6.1L and 6.4L engines. Cylinder banks, oil-pressure control, cam sensing, EVAP plumbing and catalyst locations are not interchangeable. Confirm model year, VIN, engine sales code, build date and current PCM calibration before applying any test value, bulletin or diagram."};
const town={name:"Chrysler Town & Country",kicker:"CHRYSLER TOWN & COUNTRY · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Chrysler Town & Country",about:"Chrysler Town & Country powertrain and emissions diagnostics",yearsIntro:"Town & Country OBD-II coverage crosses several minivan generations, with 3.3L and 3.8L pushrod V6 engines in earlier vans and the 3.6L Pentastar in 2011–2016 RT models. Cylinder numbering, catalyst banks, oil-pressure hardware, cam signals and EVAP routing change with that engine boundary. Decode the VIN, identify the engine and verify build date before using a bulletin or parts catalog."};

export const troubleCodeCharger:TroubleCodeGuide[]=[
 make(charger,{code:"P0456",slug:"dodge/charger/p0456",title:"P0456 Code Dodge Charger: Small EVAP Leak Diagnosis",description:"Diagnose Charger P0456 with cap, purge, ESIM and smoke tests, plus the limited 2013–2015 5.7L PCM-update branch.",definition:"EVAP System Small Leak Detected",kind:"evapSmall",quickAnswer:"P0456 means the Charger failed a very-small EVAP leak check; it does not name the gas cap. Record fuel level and filler condition, verify purge and ESIM/vent sealing, then use EVAP-safe smoke to inspect rear underbody lines, canister and tank seals. FCA bulletin 18-084-16 includes P0456 for specified 2013–2015 LD Charger 5.7L applications, but software is only a branch after physical testing and exact VIN/calibration confirmation.",yearNotes:["18-084-16 is limited to specified 2013–2015 LD Charger 5.7L applications.","V6 and HEMI purge plumbing and calibrations differ.","Rear-impact or fuel-pump service history raises underbody and tank-seal priority.","A software update cannot seal a cracked hose or leaking valve."],deepDive:[{heading:"Keep the filler untouched until it is documented",paragraphs:["A well-meaning cap tightening can erase the found condition without proving that the cap was responsible. Photograph the seal and tether area, note whether the cap was seated, and preserve fuel level and ambient temperature before clearing anything.","The Charger’s low rear body puts canister plumbing and vapor lines near road debris and lift points. Inspect clips, abrasion and repairs around the tank before assuming that a small-leak monitor failure is an electronic problem."]},{heading:"Purge and ESIM require different proof",paragraphs:["A purge solenoid can click and still pass manifold vacuum while commanded closed. Test actual sealing, because unintended purge flow can also explain a difficult restart immediately after refueling or an unexpected fuel-trim change.","The leak-detection switch and vent path must move and seal as designed. Use wiTECH functional testing where available, then section the system with regulated smoke rather than feeding unrestricted shop air into vapor components."]},{heading:"The 5.7L bulletin has hard boundaries",paragraphs:["Bulletin 18-084-16 identifies LD Charger, the 5.7L EZC/EZH sales codes and particular model years. A 3.6L Charger or a vehicle outside the calibration range does not qualify merely because P0456 appears.","Even on an eligible car, record the current software level and complete the manufacturer prechecks. A verified hose, filler or valve leak remains a physical repair; the flash branch addresses only the software behavior described by the bulletin."]}],sources:[chargerFlash,service,mopar]}),
 make(charger,{code:"P0520",slug:"dodge/charger/p0520",title:"P0520 Code Dodge Charger: Sensor Circuit or Real Oil Pressure?",description:"Diagnose Charger P0520 safely with mechanical-pressure and loaded circuit tests, including Chrysler's limited revised-sensor bulletin.",definition:"Engine Oil Pressure Sensor/Switch Circuit",kind:"oilSensor",quickAnswer:"P0520 means the PCM considers the oil-pressure sensor signal implausible, but it cannot guarantee that engine pressure is safe. Shut down for a warning or noise, verify oil and filter, compare a mechanical gauge with scan data, then load-test the sensor circuits and connector. Bulletin 18-034-14 Rev. A lists 2013–2014 Charger applications built by its cutoff for a revised sensor; verify engine, VIN/RRT status and build date before using that repair.",yearNotes:["18-034-14 Rev. A lists 2013–2014 Charger applications within its engine and build-date limits.","Pentastar and HEMI pressure specifications and sensor access differ.","P0522 or P0523 provides useful signal-voltage direction.","A red oil-pressure warning or engine noise takes priority over the code description."],deepDive:[{heading:"Mechanical pressure decides whether the engine may run",paragraphs:["Start with oil level, viscosity, filter part and visible leaks, but do not treat a normal dipstick reading as proof of pressure. Install the specified gauge and compare pressure at the exact oil temperature and rpm in engine-specific service information.","If pressure is genuinely low, stop electrical parts swapping and diagnose pickup, filter flow, pump, clearances and oil-control hardware. Continued operation can damage bearings and valvetrain even when the dash reading occasionally returns."]},{heading:"Test the signal as a circuit, not a connector glance",paragraphs:["Oil intrusion, weak terminal tension and heat-related harness opens can create an intermittent P0520. Backprobe or use the approved breakout method, load-test reference and ground, and compare sensor voltage with both mechanical pressure and scan pressure.","An ohmmeter can show continuity through a high-resistance connection that fails under load. Reproduce the temperature and vibration from freeze-frame data and inspect the harness where it bends around the intake or engine covers."]},{heading:"The revised-sensor bulletin is not universal",paragraphs:["Chrysler’s 18-034-14 Rev. A lists model, engine sales codes, a March 12, 2014 build cutoff and VIN/RRT verification. Confirm all of those facts rather than applying a catalog sensor to every Charger carrying P0520.","A revised sensor may correct an eligible circuit concern, but it cannot fix verified low mechanical pressure. Record the gauge result before replacement and confirm agreement between gauge, scan value and warning behavior after repair."]}],sources:[p0520,service,mopar]}),
 make(charger,{code:"P06DD",slug:"dodge/charger/p06dd",title:"P06DD Code Dodge Charger: Pentastar Oil-Pressure Control Tests",description:"Diagnose Charger P06DD through oil, filter, mechanical pressure, feedback and control tests, with the narrow early-3.6L software branch.",definition:"Engine Oil Pressure Control Circuit Stuck Off",kind:"oilControl",quickAnswer:"On a 3.6L Pentastar Charger, P06DD means commanded oil-pressure control did not produce the expected response. Verify the exact oil and filter, prove pressure mechanically, compare desired and actual pressure, and test sensor feedback plus control wiring before condemning the pump. Bulletin 18-085-15 includes P06DD for 2011–2012 LD Charger 3.6L vehicles, but later cars and HEMI engines require their own diagnostic information.",yearNotes:["18-085-15 identifies 2011–2012 LD Charger with the 3.6L ERB.","HEMI lubrication systems do not inherit the Pentastar P06DD procedure.","P0520/P0522 must be resolved when pressure feedback is unreliable.","Oil/filter service immediately before the code is important evidence."],deepDive:[{heading:"P06DD describes a failed commanded response",paragraphs:["The PCM expects the dual-stage system to change pressure under defined operating conditions. A wrong filter, restricted passage, control-circuit fault, biased sensor or hydraulic failure can all prevent that expected transition, so the word “stuck” is not a pump verdict.","Graph commanded state, sensor pressure, rpm and oil temperature while comparing with a mechanical gauge. Do not force a high-rpm test if the warning is active, the engine is noisy or gauge pressure is already unsafe."]},{heading:"Audit the last oil service before opening the engine",paragraphs:["Record oil grade, fill level, filter manufacturer and element installation. A collapsed or incorrect element, cap sealing error or debris in the housing can alter flow and should be corrected before expensive oil-pump work.","Inspect for external leakage and filter-housing evidence without assuming every wet area is the housing itself. Clean or use dye as appropriate so oil running from another seal is not mistaken for a pressure-control component failure."]},{heading:"Early software coverage does not transfer forward",paragraphs:["FCA bulletin 18-085-15 covers specified 2011–2012 LD Charger 3.6L applications and lists P06DD among several software improvements. It does not establish a flash repair for a later Pentastar or any HEMI Charger.","For an eligible VIN, confirm current PCM level and complete the bulletin prerequisites. For all others, follow year- and engine-specific pressure specifications, electrical pin tests and hydraulic diagnosis until one failure is measured."]}],sources:[earlyP06dd,service,mopar]}),
 make(charger,{code:"P0128",slug:"dodge/charger/p0128",title:"P0128 Code Dodge Charger: Thermostat and Warm-Up Diagnosis",description:"Diagnose Charger P0128 by graphing cold ECT, road-speed warm-up and fan operation for the exact V6 or HEMI cooling system.",definition:"Thermostat Rationality",kind:"warmup",quickAnswer:"P0128 means coolant temperature did not rise or regulate as the Charger PCM expected. A leaking-open thermostat is common, but low coolant, trapped air, biased ECT data, unwanted fan operation or an incorrect thermostat can produce the same result. Compare ECT and intake-air temperature after an overnight soak, then graph ECT, load, speed and fan command through a real drive. Match the thermostat and bleeding procedure to the exact V6 or HEMI engine.",yearNotes:["2.7L, 3.5L, 3.6L and HEMI cooling systems use different parts and bleed procedures.","A temperature drop at highway speed strongly supports thermostat leakage.","The instrument-panel gauge is damped and cannot replace scan data.","Overheating, coolant loss or heater output suddenly going cold requires stopping."],deepDive:[{heading:"Begin with an undisturbed cold-soak comparison",paragraphs:["Before startup, ECT and intake-air temperature should be close to each other and to ambient after enough soak time. A large disagreement exists before the thermostat can influence temperature and therefore raises sensor, connector or calibration questions.","Check coolant only when cold and inspect the reservoir, cap, hose joints and recent service history. Air trapped after cooling-system work can make heater output and sensor readings unstable, confusing the rationality monitor."]},{heading:"A drive graph shows what the dash gauge hides",paragraphs:["Plot ECT against elapsed time, vehicle speed, engine load, fan command and cabin-heat use. A steady climb followed by a repeatable drop during highway airflow is more persuasive thermostat evidence than a vague complaint that the car warms slowly.","A fan running without PCM command can also remove too much heat. Compare commanded and actual fan behavior before replacing a thermostat, particularly if electrical or air-conditioning work preceded the code."]},{heading:"Engine identification prevents a second repair",paragraphs:["The longitudinal Charger platform has used several V6 and HEMI cooling arrangements. Thermostat temperature rating, housing design, fill point and air-bleed method must come from the exact engine and model-year procedure.","After repair, verify stable operating temperature in the original weather and road conditions, dependable cabin heat and no pending P0128. Clearing the lamp alone does not demonstrate that the monitor can now pass."]}]}),
 make(charger,{code:"P0300",slug:"dodge/charger/p0300",title:"P0300 Code Dodge Charger: Random Misfire by V6 and HEMI",description:"Diagnose Charger P0300 with cylinder counters, bank patterns, plugs, coils, fuel and compression—plus limited factory bulletin branches.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple cylinders misfired or no single cylinder dominated. Preserve P0301–P0308 counters, fuel trims and freeze-frame load before moving parts. V6 and HEMI Chargers have different numbering, banks and valvetrain risks. Bulletin 18-084-16 includes a P0300 software branch for specified 2013–2015 5.7L Chargers; bulletin 09-002-14 covers defined 2011–2013 3.6L cars only when P0300 or even-cylinder codes meet its leakage criteria. Neither bulletin replaces ignition, fuel and mechanical testing.",yearNotes:["3.6L Pentastar and HEMI cylinder layouts and firing orders differ.","The X56 extension lists P0300/P0302/P0304/P0306—not P0301.","18-084-16 is a separate 2013–2015 LD 5.7L software branch.","A flashing MIL requires reducing load immediately to protect the catalysts."],deepDive:[{heading:"Let cylinder and bank patterns choose the branch",paragraphs:["Save individual misfire counters during the same cold start, idle or loaded condition that set the code. One cylinder supports a targeted plug, coil, injector and compression path; one bank raises local air, fuel, exhaust or cam-timing causes.","Misfires spread across both banks move shared fuel pressure, contaminated fuel, charging voltage and major air-metering faults higher. Do not scatter coils across the engine before recording the structure that made P0300 diagnostically useful."]},{heading:"The Pentastar head extension has exact criteria",paragraphs:["Bulletin 09-002-14 Rev. B applies to listed 2011–2013 LD Charger 3.6L vehicles with P0300, P0302, P0304 or P0306. It directs a leakage test on cylinders 2, 4 and 6 and uses a 25-percent threshold in its repair decision.","That document is not proof that every Pentastar misfire needs a cylinder head. A P0301-only complaint, a later vehicle or normal leakage requires the ordinary evidence-led path through ignition, injection, air and compression."]},{heading:"The HEMI software branch still requires physical checks",paragraphs:["Bulletin 18-084-16 lists P0300 for specified 2013–2015 LD Charger 5.7L applications, but a calibration update cannot repair a worn plug, injector imbalance, intake leak or mechanical valvetrain fault.","Confirm the engine sales code and current calibration, then follow bulletin prerequisites only if the VIN matches. Verify the repair under the original condition without repeatedly driving through a flashing-MIL event that can overheat both catalysts."]}],sources:[pentastarHead,chargerFlash,service,mopar]}),
 make(charger,{code:"P0455",slug:"dodge/charger/p0455",title:"P0455 Code Dodge Charger: Large EVAP Leak Test Plan",description:"Find Charger P0455 using filler, purge, ESIM, canister, rear vapor-line and tank-seal tests instead of guessing at a gas cap.",definition:"EVAP System Large Leak Detected",kind:"evapLarge",quickAnswer:"P0455 means the Charger EVAP system could not establish or retain the expected seal. Inspect the cap or capless filler without disturbing evidence, test purge and ESIM/vent valves for actual sealing, and smoke-test rear lines, canister and top-of-tank connections at regulated pressure. A disconnected hose and a valve held open can look identical to the PCM. P0456 software bulletins do not automatically apply to this larger-leak code.",yearNotes:["EVAP routing changes across LX/LD years and fuel-system revisions.","Rear collision, exhaust or fuel-pump work can disturb vapor lines.","Hard starting after refueling increases purge-leak priority.","Strong vapor odor or liquid fuel requires stopping and safe inspection."],deepDive:[{heading:"A large leak may be an open normal passage",paragraphs:["The purge and vent paths are designed to open during normal operation, so either valve held open can prevent the test from sealing. Commanding a solenoid and hearing a click only proves movement or current, not leak-tight closure.","Isolate purge from the manifold and verify closed-state flow, then operate the leak-detection or vent device according to the exact service procedure. This prevents an expensive tank search when a front-of-car valve is the open path."]},{heading:"Follow recent work along the rear of the car",paragraphs:["Charger vapor lines cross a low underbody and terminate around the rear canister and tank. Inspect displaced clips, crushed tubing, road impact and quick-connects after exhaust, rear suspension, collision or fuel-pump work.","Use EVAP-safe regulated smoke and section the system so the plume identifies a component boundary. Unrestricted shop pressure risks damaging the canister or tank and can turn a diagnostic job into a safety problem."]},{heading:"Verify the monitor, not only the absence of smoke",paragraphs:["A repaired gross leak may still require an overnight soak and a permitted fuel-level range before the PCM reruns its monitor. Preserve pending-code and readiness status instead of repeatedly clearing memory.","If no physical leak is found, validate pressure-switch or ESIM data and circuit integrity using the correct model-year schematic. A false leak-detection signal must be proven; replacing the PCM or canister by elimination is not a test."]}]}),
 make(charger,{code:"P0420",slug:"dodge/charger/p0420",title:"P0420 Code Dodge Charger: Bank 1 Catalyst Diagnosis",description:"Diagnose Charger P0420 by identifying Bank 1, correcting misfire, mixture, oil use and exhaust leaks, then testing sensors and catalyst.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means Bank 1 catalyst oxygen-storage performance fell below the PCM threshold. Identify Bank 1 from the exact Charger engine diagram, save P0430 and misfire context, and repair fuel-control, oil/coolant consumption and exhaust-leak faults before judging the converter. Compare both banks under identical load. A downstream oxygen sensor that resembles the upstream signal is evidence to investigate, not automatic proof that the sensor or catalyst is bad.",yearNotes:["V6 and HEMI Bank 1 locations and exhaust packaging differ.","P0430 supplies valuable same-engine Bank 2 comparison.","HEMI MDS or valvetrain misfire can damage a converter but must be proven.","Aftermarket exhaust parts and leaks can change monitor behavior."],deepDive:[{heading:"Bank 2 is a built-in control group",paragraphs:["Graph upstream and downstream activity, trims and misfire counts for both banks during the same stabilized drive. A Bank 1/Bank 2 split can reveal a local injector, manifold leak or cylinder issue that a single sensor trace hides.","Use the exact engine’s cylinder-numbering and bank drawing. Guessing the side on a longitudinal V6 or HEMI can lead to replacing the good converter and leaving the failing bank untouched."]},{heading:"A catalyst often records damage caused upstream",paragraphs:["Repeated misfire, rich operation and oil or coolant entry can reduce oxygen storage or melt the substrate. Review permanent codes, plug deposits, injector balance and fluid-consumption history before authorizing converter replacement.","Listen for substrate rattle and test restriction if power loss is present. With a flashing MIL, stop sustained driving—the active misfire can overheat a new catalyst just as quickly as the original one."]},{heading:"Sensor shape alone is not a parts order",paragraphs:["A downstream sensor normally changes more slowly than the upstream unit, but heater, bias and exhaust leaks can distort both signals. Check circuit response and inspect the exhaust cold for soot or ticking at joints ahead of the sensor.","Only evaluate catalyst efficiency after readiness prerequisites and catalyst-damaging faults are resolved. Confirm repair by completing the monitor without pending P0420, rather than by clearing the lamp in the driveway."]}]}),
 make(charger,{code:"P0301",slug:"dodge/charger/p0301",title:"P0301 Code Dodge Charger: Cylinder 1 Misfire Diagnosis",description:"Diagnose Charger P0301 with correct cylinder location, a controlled ignition test, injector contribution, compression and timing evidence.",definition:"Cylinder 1 Misfire Detected",kind:"cyl1",quickAnswer:"P0301 localizes misfire to physical cylinder 1 but does not identify a failed coil. Confirm cylinder 1 on the exact Charger V6 or HEMI diagram, preserve counters, inspect the labeled plug and perform one controlled ignition test. If the count remains on cylinder 1, test injector contribution, runner leakage, compression and leak-down. The 2011–2013 Pentastar X56 bulletin lists even-cylinder misfires and P0300—not P0301—so it must not be used as an automatic cylinder-head diagnosis here.",yearNotes:["Cylinder 1 location differs by engine family; use an exact diagram.","09-002-14 Rev. B does not list P0301 among its qualifying codes.","P0340/P0016 or startup rattle raises synchronization priority.","A flashing MIL means stop loading the catalysts."],deepDive:[{heading:"Perform one controlled ignition experiment",paragraphs:["Label the cylinder 1 plug and coil, record the count, and move only the testable ignition component to a known cylinder. Reproduce the same cold, idle or load condition while watching counters instead of judging solely by sound.","If the misfire follows, the test has isolated an ignition component. If it stays on cylinder 1, return the known-good component and move to injector, intake-runner and mechanical tests rather than continuing random swaps."]},{heading:"The removed plug is a diagnostic sample",paragraphs:["Compare cylinder 1 with a neighboring plug from the same bank. Excess gap, fuel wetness, oil ash, coolant-cleaned porcelain or impact damage support different next steps, so keep each plug labeled and photograph deposits.","An electrically firing plug can still reveal injector overfueling or loss of cylinder sealing. Replacing all plugs before examining them discards the best cylinder-specific evidence the code provided."]},{heading:"Do not misapply the Pentastar head bulletin",paragraphs:["The X56 extension names P0300, P0302, P0304 and P0306 on specified 2011–2013 3.6L vehicles and directs leakage testing of even cylinders. P0301 alone does not meet that code list.","Cylinder 1 can still have a mechanical fault, but compression, running contribution and leak-down must demonstrate it. If cam/crank codes accompany the misfire, inspect synchronization and valvetrain evidence before condemning an injector or coil."]}],sources:[pentastarHead,service,mopar]}),
 make(charger,{code:"P0340",slug:"dodge/charger/p0340",title:"P0340 Code Dodge Charger: Cam Sensor Circuit Diagnosis",description:"Diagnose Charger P0340 with engine-specific sensor identification, loaded wiring checks and cam/crank waveform comparison.",definition:"Camshaft Position Sensor Circuit",kind:"cam",quickAnswer:"P0340 means the Charger PCM lost or rejected the expected cam-position signal; it does not prove the sensor itself failed. Identify the correct cam circuit for the V6 or HEMI, inspect harness routing, load-test reference, ground and signal, then scope cam against crank. Dropout or noise supports a circuit or sensor path, while clean signals with stable phase error and P0016 shift attention toward the phaser, chain or reluctor.",yearNotes:["3.6L Pentastar uses multiple cam sensors; HEMI architecture differs.","Older 2.7L and 3.5L engines require their own signal patterns.","P0335 or several sensor codes may expose shared wiring or voltage.","Stalling, no-start or timing noise makes diagnosis urgent."],deepDive:[{heading:"Name the circuit before buying a sensor",paragraphs:["Read every code and use the VIN-correct schematic to identify connector, bank and shared supplies. A generic parts listing cannot show whether the stored code concerns one cam sensor, a shared reference branch or plausibility against crank position.","Inspect harness bends near engine covers, brackets and hot components. Terminal spread or an internally broken wire may fail only when heat, vibration or engine movement recreates the original condition."]},{heading:"Loaded voltage tests expose false continuity",paragraphs:["Verify reference voltage and ground with the circuit carrying an appropriate load. A digital meter can display full voltage through corrosion or a nearly open strand even though the signal collapses when the sensor operates.","Check terminal tension and contamination before piercing insulation. If multiple sensors share a supply and set codes together, disconnect branches methodically to find the short rather than replacing each sensor."]},{heading:"Use one capture to separate dropout from timing",paragraphs:["Scope cam and crank simultaneously during crank, idle and the temperature where the fault occurs. Missing edges, noise or amplitude loss favor sensor, air-gap, connector or harness causes.","A repeatable phase displacement between otherwise clean signals points toward mechanical timing, a phaser or reluctor position. That evidence justifies deeper inspection; P0340 wording alone does not."]}]}),
 make(charger,{code:"P0016",slug:"dodge/charger/p0016",title:"P0016 Code Dodge Charger: Cam/Crank Correlation Diagnosis",description:"Diagnose Charger P0016 using oil condition, desired/actual cam data, circuit checks and scoped mechanical timing evidence.",definition:"Crankshaft–Camshaft Correlation (Bank 1 Sensor A)",kind:"correlation",quickAnswer:"P0016 means the measured Bank 1 Sensor A cam relationship did not agree with crank position. Confirm the exact engine definition, save desired and actual cam angles, verify oil and filter, resolve P0340/P0335 signal faults, and scope both signals together. Intermittent missing edges support a circuit problem; a stable offset, startup rattle or failed phaser response supports mechanical timing, oil-control, reluctor or phaser inspection. Replacing both sensors is not a diagnosis.",yearNotes:["Bank 1 Sensor A must be identified from exact engine service information.","Pentastar, 2.7L/3.5L V6 and HEMI timing systems differ.","Wrong or low oil can interfere with phaser response on equipped engines.","Persistent rattle, stalling or severe misfire warrants prompt shutdown and inspection."],deepDive:[{heading:"Correlation is a relationship, not a component name",paragraphs:["Both sensors may generate signals while their timing relationship is wrong, or one valid mechanical system may be falsely accused by an intermittent signal dropout. Save synchronized cam and crank data before deciding which branch applies.","Compare desired and actual cam angle where scan data supports it. A phaser that lags command only under hot-oil conditions presents differently from a harness dropout that removes individual waveform edges."]},{heading:"Oil quality is part of variable-cam operation",paragraphs:["Check level, viscosity, filter and sludge history before commanding phasers. Low oil, incorrect viscosity or a restricted control passage can delay movement and create correlation errors without a stretched chain.","Do not mask noise with thicker oil. Correct the service prerequisite and use the engine-specific actuation test; stop if mechanical pressure or valvetrain noise indicates unsafe operation."]},{heading:"A stable offset justifies mechanical inspection",paragraphs:["Clean cam and crank patterns that remain displaced point toward chain indexing, guide or tensioner wear, phaser position or a moved reluctor. Compare with a known-good pattern for that exact engine and model year.","After repair, perform any required relearn and verify hot and cold synchronization with no pending P0016. A cleared code immediately after parts installation is not sufficient evidence."]}]}),
];

export const troubleCodeTownCountry:TroubleCodeGuide[]=[
 make(town,{code:"P0456",slug:"chrysler/town-and-country/p0456",title:"P0456 Code Chrysler Town & Country: Small EVAP Leak Guide",description:"Diagnose Town & Country P0456 with cap, purge, ESIM, canister and tank-line tests matched to the exact minivan generation.",definition:"EVAP System Small Leak Detected",kind:"evapSmall",quickAnswer:"P0456 means the Town & Country EVAP monitor detected a very small loss of sealing. Preserve the cap and fuel-level evidence, test purge closed-state sealing and the leak-detection/vent device, then use regulated smoke around long underbody vapor lines, canister and tank-module seals. Earlier 3.3L/3.8L vans and 2011–2016 3.6L RT vans do not share every component or calibration, so identify the engine and year before ordering parts.",yearNotes:["Earlier 3.3L/3.8L and later 3.6L vans use different EVAP layouts.","A 2015 NHTSA investigation record documents P0456/P0441 on a 2015 3.6L but is not a repair bulletin.","Fuel-pump or rear-underbody work raises line and tank-seal priority.","Hard starting after refueling strongly supports testing purge leakage."],deepDive:[{heading:"Minivan packaging changes the inspection route",paragraphs:["Vapor plumbing runs from the engine bay toward a large rear fuel tank and canister area. Follow it end to end for rubbed tubing, displaced clips and quick-connects disturbed during exhaust, tank or rear-heater work.","Do not assume the newest diagram fits an earlier 3.8L van. Use VIN and engine information to identify the purge valve, leak-detection device and service ports before smoke testing."]},{heading:"A tiny leak needs controlled conditions",paragraphs:["Record fuel level, soak temperature and whether the lamp followed refueling. Small-leak monitors are gated by conditions, so clearing the code before saving freeze frame can make an intermittent leak much harder to reproduce.","Test the filler seal and purge valve without first changing them. A purge valve that passes manifold vacuum while commanded closed can cause both P0456 and a rough or difficult hot restart after filling."]},{heading:"Smoke confirms location, not just existence",paragraphs:["Use EVAP-rated equipment at the manufacturer’s limited pressure and isolate sections of the system. A faint plume at the cap, canister seam, hose connection or pump-module seal gives a repairable location.","After repair, rerun supported wiTECH leak verification and allow readiness conditions to complete. No visible smoke plus an immediately cleared lamp is not the same as a passed monitor."]}]}),
 make(town,{code:"P0520",slug:"chrysler/town-and-country/p0520",title:"P0520 Code Chrysler Town & Country: Oil Pressure Safety Test",description:"Separate Town & Country P0520 electrical faults from true low oil pressure, including the limited 2013–2014 revised-sensor bulletin.",definition:"Engine Oil Pressure Sensor/Switch Circuit",kind:"oilSensor",quickAnswer:"P0520 means the PCM distrusts the oil-pressure sensor circuit, not that pressure is safely normal. Stop for a warning or valvetrain noise, verify oil and filter, compare mechanical gauge pressure with scan data, and load-test reference, ground, signal and connector. Chrysler bulletin 18-034-14 Rev. A lists 2013–2014 RT Town & Country within its engine/build-date scope for a revised sensor. Confirm VIN/RRT status before applying that repair.",yearNotes:["18-034-14 Rev. A lists 2013–2014 RT Town & Country under stated engine and build limits.","3.3L/3.8L and 3.6L pressure systems require different specifications.","P0522/P0523 signal direction helps localize electrical faults.","Noise or a red oil warning requires shutting down before diagnosis."],deepDive:[{heading:"Protect the engine before diagnosing the sender",paragraphs:["Check the cold oil level, correct viscosity, filter and visible leaks, then install the specified mechanical gauge. Compare pressure at the oil temperature and rpm given for the exact engine rather than using a generic idle number.","If gauge pressure is below specification, stop running and diagnose the pickup, pump, filter flow, clearances or control system. A new sensor cannot protect bearings from a verified lubrication failure."]},{heading:"The connector lives in a difficult environment",paragraphs:["Heat, oil contamination and repeated intake-service handling can weaken terminal grip or damage the harness. Inspect each terminal, then load-test reference and ground while comparing the signal with mechanical and scan pressure.","Perform wiggle and heat testing only while pressure is known safe. A static continuity result is weak evidence because a corroded strand may pass meter current yet fail during operation."]},{heading:"Apply the 2013–2014 sensor bulletin precisely",paragraphs:["Bulletin 18-034-14 Rev. A sets vehicle, engine-sales-code, build-date and VIN/RRT boundaries. It also identifies a revised sensor repair; it does not say every Town & Country with P0520 has that sensor defect.","Document the original gauge-to-scan disagreement and confirm both values agree after repair. If the code returns with normal wiring and sensor response, continue factory diagnosis instead of installing another sensor."]}],sources:[p0520,service,mopar]}),
 make(town,{code:"P06DD",slug:"chrysler/town-and-country/p06dd",title:"P06DD Code Chrysler Town & Country: 3.6L Oil-Control Diagnosis",description:"Diagnose Town & Country P06DD with oil, filter, mechanical-pressure and control tests plus the narrow early-2011 software branch.",definition:"Engine Oil Pressure Control Circuit Stuck Off",kind:"oilControl",quickAnswer:"On the 3.6L Pentastar Town & Country, P06DD means the commanded oil-pressure stage did not produce the expected feedback. Verify oil, filter and housing service, prove pressure mechanically, compare commanded state with sensor data, and test feedback plus control wiring. FCA bulletin 18-085-15 includes P06DD only for 2011 RT 3.6L vans built before March 12, 2011. It does not establish a flash repair for later vans or older 3.3L/3.8L engines.",yearNotes:["18-085-15 is limited to early-build 2011 RT 3.6L ERB vehicles.","The 3.3L and 3.8L engines do not use the same Pentastar diagnostic branch.","P0520/P0522 can make pressure feedback unreliable.","A recent oil/filter service is important diagnostic history."],deepDive:[{heading:"Commanded pressure, feedback and hydraulics must agree",paragraphs:["P06DD is a system-performance result. The PCM commands a pressure state and evaluates feedback, so an incorrect filter, biased sensor, control-circuit fault, restricted passage or pump problem can all violate the expected response.","Use scan data and a mechanical gauge together at safe temperature and rpm. Do not repeatedly rev a noisy engine or one displaying an oil warning merely to force the high-pressure stage."]},{heading:"Inspect service details before replacing the pump",paragraphs:["Record oil grade, fill amount, filter element and cap installation. An incorrect or collapsed filter and seal mistakes should be corrected before internal engine work, especially when the code appeared immediately after service.","Inspect the oil-filter housing area and clean or dye-trace leakage so the source is known. Oil running from a cap, cooler connection or adjacent seal does not by itself prove an internal pressure-control failure."]},{heading:"The early-2011 calibration branch is narrow",paragraphs:["Bulletin 18-085-15 names the RT Town & Country 3.6L built before March 12, 2011 and includes P06DD among several PCM improvements. A 2012–2016 van is outside that stated branch.","For a matching VIN, confirm the current calibration and complete factory prerequisites. For other vehicles, follow the exact mechanical-pressure, solenoid-circuit and hydraulic tests until one failed element is measured."]}],sources:[earlyP06dd,service,mopar]}),
 make(town,{code:"P0128",slug:"chrysler/town-and-country/p0128",title:"P0128 Code Chrysler Town & Country: Warm-Up Test by Engine",description:"Diagnose Town & Country P0128 with cold sensor comparison, coolant checks and a road-load warm-up graph for the correct V6.",definition:"Thermostat Rationality",kind:"warmup",quickAnswer:"P0128 means the van did not warm up or regulate coolant temperature as quickly as its PCM model expected. A stuck-open thermostat is common, but low coolant, trapped air, biased ECT data, unwanted fan operation and an incorrect thermostat can mimic it. Compare ECT and intake-air temperature after a long cold soak, then graph ECT, load, speed, heater use and fan command. Use the exact 3.3L, 3.8L or 3.6L cooling procedure.",yearNotes:["3.3L/3.8L and 3.6L thermostat locations and bleeding procedures differ.","Rear-heater plumbing increases coolant volume and potential air pockets on equipped vans.","The dashboard gauge is damped; scan ECT is needed.","Stop for overheating, steam, coolant loss or heater output suddenly turning cold."],deepDive:[{heading:"Rear heat makes system history especially relevant",paragraphs:["Town & Country cooling systems may include long rear-heater lines and additional coolant volume. Recent hose, radiator, water-pump or rear-heater work can leave low level or trapped air that changes warm-up and cabin-heat behavior.","Check the cold level and inspect the entire known circuit for leakage. Never open a hot cap, and do not declare the thermostat faulty while the system is underfilled or improperly bled."]},{heading:"Cold sensor comparison separates bias from regulation",paragraphs:["After an overnight soak, ECT and intake-air temperature should approach ambient. A significant disagreement at key-on exists before coolant begins circulating and therefore points toward a sensor or circuit branch.","If the sensors agree, graph warm-up during actual driving. Include speed, load, fan command and front/rear heater use so a road-speed temperature drop can be distinguished from a fan or load effect."]},{heading:"Verify stable regulation under the original conditions",paragraphs:["A thermostat leaking open often produces a slow rise and a repeatable drop during steady highway airflow, while a biased sensor may remain implausible in a different pattern. Use data rather than relying on the broad center position of the dash gauge.","Install the engine-correct part and follow its bleed method. Confirmation requires stable heat, correct scan temperature and a completed monitor without pending P0128 in comparable weather."]}]}),
 make(town,{code:"P0300",slug:"chrysler/town-and-country/p0300",title:"P0300 Code Chrysler Town & Country: Pentastar Misfire Diagnosis",description:"Diagnose Town & Country P0300 with cylinder patterns, plugs, coils, fuel and leakage tests plus exact factory bulletin boundaries.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means several cylinders misfired or no single cylinder dominated. Preserve individual counters, trims, coolant temperature and load before moving coils. Earlier 3.3L/3.8L engines and the 3.6L Pentastar need different numbering and tests. Bulletin 09-002-14 covers specified 2011–2013 3.6L vans with P0300 or even-cylinder misfires and requires leakage testing; separate PCM bulletins cover defined 2012 and 2015–2016 3.6L applications. Verify the exact branch instead of assuming a head or software repair.",yearNotes:["09-002-14 covers listed 2011–2013 RT 3.6L vehicles and specified code/leakage criteria.","18-104-15 applies to a defined 2012 RT 3.6L/DG2 combination.","18-085-16 includes a 2015 cold-idle P0300 branch through its stated 2016 build cutoff.","3.3L and 3.8L vans do not inherit Pentastar bulletins."],deepDive:[{heading:"Cylinder distribution is more valuable than the generic code",paragraphs:["Capture individual-cylinder counts during the original cold start, idle or loaded event. One leader supports a targeted ignition, injector and compression path; even-cylinder concentration on an eligible early Pentastar raises the factory leakage-test branch.","If both banks participate, investigate shared fuel quality or pressure, charging voltage, purge leakage and major air-metering faults. Avoid rearranging multiple coils before the original pattern is recorded."]},{heading:"The X56 extension requires evidence",paragraphs:["Bulletin 09-002-14 Rev. B names specified 2011–2013 RT 3.6L vans with P0300, P0302, P0304 or P0306. It directs leakage testing of cylinders 2, 4 and 6 and uses 25 percent or greater leakage in its decision path.","That is not permission to replace every Pentastar head. Normal leakage, different cylinders, a later model year or another engine returns the diagnosis to plugs, ignition, injectors, intake sealing, fuel delivery and mechanical tests."]},{heading:"Software branches are year-specific",paragraphs:["Bulletin 18-104-15 lists P0300–P0306 for a defined 2012 RT 3.6L with DG2 transmission. Bulletin 18-085-16 identifies a cold-idle P0300 condition for 2015 vehicles within its 2015–2016 build scope.","Check VIN, build date, transmission and current PCM level before considering either update. A calibration cannot restore compression or repair a worn plug, and a flashing MIL still requires reducing load to protect the catalysts."]}],sources:[pentastarHead,town2012Flash,townColdMisfire,service,mopar]}),
 make(town,{code:"P0455",slug:"chrysler/town-and-country/p0455",title:"P0455 Code Chrysler Town & Country: Large EVAP Leak Diagnosis",description:"Locate Town & Country P0455 with filler, purge, vent, long underbody-line, canister and tank-seal tests.",definition:"EVAP System Large Leak Detected",kind:"evapLarge",quickAnswer:"P0455 means the Town & Country EVAP test found a gross sealing loss or could not close a normal vapor path. Preserve filler condition and service history, prove purge and leak-detection/vent sealing, then use regulated smoke along the van’s underbody lines, rear canister and tank-module connections. A disconnected quick-connect or valve held open may look like a hole in the tank. Match component names and routing to the exact generation and engine.",yearNotes:["EVAP layout differs between earlier 3.3L/3.8L vans and 2011–2016 Pentastar models.","Tank, fuel-pump, exhaust and rear HVAC work can disturb rear vapor plumbing.","P0456 calibration information is not automatically applicable to P0455.","Fuel odor or visible wetness requires parking safely and stopping diagnosis until leakage is controlled."],deepDive:[{heading:"Start where the vehicle was last disturbed",paragraphs:["Ask whether the code followed fuel-pump access, tank removal, exhaust work, collision repair or rear-heater service. Inspect quick-connects, clips and long vapor lines around those areas before replacing a canister.","Document the cap or filler before touching it. A missing or damaged seal is useful evidence, while tightening it first only proves that someone changed the test condition."]},{heading:"Valves can create a gross leak without a broken hose",paragraphs:["A purge valve passing manifold vacuum while commanded closed or a vent/leak-detection device that cannot seal leaves a normal passage open. Test mechanical sealing; an audible click is not enough.","Once valves pass, section the system with EVAP-rated smoke pressure. Isolating the front line, canister and tank reduces test volume and makes a plume at a seal or cracked hose easier to locate."]},{heading:"A completed monitor is the final proof",paragraphs:["Repair damage with emission-rated parts and ensure lines are routed away from heat, sharp edges and moving suspension. Validate switch or ESIM data if the physical system holds pressure but the PCM still reports a leak.","The EVAP monitor may require a defined fuel level and cold soak. Confirm readiness and no pending P0455 rather than repeatedly erasing memory and assuming the lamp’s temporary absence is success."]}]}),
 make(town,{code:"P0420",slug:"chrysler/town-and-country/p0420",title:"P0420 Code Chrysler Town & Country: Bank 1 Catalyst Tests",description:"Diagnose Town & Country P0420 by correcting misfire, mixture, oil use and exhaust leaks before testing Bank 1 sensors and catalyst.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means Bank 1 catalyst oxygen-storage performance was below threshold. Identify Bank 1 for the exact V6, preserve P0430 and misfire context, and correct mixture, oil/coolant consumption and exhaust leaks before evaluating the converter. Chrysler bulletin 18-104-15 lists a temperature-related P0420 software branch for a specific 2012 RT Town & Country 3.6L with DG2 transmission. That narrow branch does not apply to every year or engine.",yearNotes:["18-104-15 applies to a specified 2012 RT 3.6L/DG2 vehicle and notes P0420 at 85°F/29°C or higher.","3.3L, 3.8L and 3.6L catalyst layouts differ.","P0430 provides a useful Bank 2 comparison on dual-bank systems.","An active misfire can quickly damage replacement catalysts."],deepDive:[{heading:"Compare the banks before condemning a converter",paragraphs:["Graph upstream and downstream sensor activity, fuel trims and misfire counts for both banks during the same stabilized drive. A strong side-to-side difference can reveal a local injector, intake leak or exhaust leak upstream of Bank 1.","Confirm cylinder numbering and Bank 1 with the exact engine diagram. The minivan’s transverse layout can make internet left/right descriptions ambiguous when viewed from the grille or driver’s seat."]},{heading:"Repair catalyst-damaging faults first",paragraphs:["Review P030x history, plug deposits, injector balance and oil or coolant consumption. A converter may be the damaged result of another failure, and replacing it alone allows the original cause to damage the new part.","Inspect the exhaust cold for cracks, soot and loose joints ahead of the sensors. Test restriction if the van rattles or loses power; stop driving under a flashing MIL or severe restriction."]},{heading:"The 2012 calibration note has a temperature clue",paragraphs:["Bulletin 18-104-15 lists P0420 and P0430 occurring at 85°F (29°C) or higher for the specified 2012 RT 3.6L with DG2 transmission. Confirm every application detail and current software before using it.","Other vans require ordinary circuit, combustion and catalyst testing. Final proof is a completed catalyst monitor with no pending P0420 after prerequisites are repaired—not simply a downstream sensor replacement."]}],sources:[town2012Flash,service,mopar]}),
 make(town,{code:"P0301",slug:"chrysler/town-and-country/p0301",title:"P0301 Code Chrysler Town & Country: Cylinder 1 Misfire Tests",description:"Diagnose Town & Country P0301 with correct cylinder location, plug and coil evidence, injector testing, compression and bulletin boundaries.",definition:"Cylinder 1 Misfire Detected",kind:"cyl1",quickAnswer:"P0301 identifies physical cylinder 1 misfire but does not name a coil or injector. Confirm cylinder 1 on the exact 3.3L, 3.8L or 3.6L layout, inspect the labeled plug, perform one controlled ignition test, then test injector contribution and compression if the count stays. Bulletin 18-104-15 includes P0301 for a specified 2012 3.6L/DG2 software branch, while the X56 cylinder-head extension lists P0300 and even-cylinder codes—not P0301.",yearNotes:["Cylinder 1 location and ignition hardware differ between pushrod and Pentastar V6 engines.","18-104-15 includes P0301 only for its defined 2012 RT 3.6L/DG2 application.","09-002-14 Rev. B does not list P0301 as a qualifying X56 code.","P0340/P0016 companions raise cam/crank synchronization priority."],deepDive:[{heading:"Use the counter to control one swap",paragraphs:["Label cylinder 1 components and record the misfire count under its original cold, idle or load condition. Move only a testable ignition component, then watch whether the count follows rather than replacing an entire set by assumption.","If the fault remains on cylinder 1, return the known-good component and evaluate the plug, injector command and flow, local intake leakage, compression and leak-down. Continued swapping destroys the control comparison."]},{heading:"Read the plug before discarding it",paragraphs:["Compare plug 1 with another cylinder and keep both positions labeled. Raw-fuel wetness, heavy oil ash, unusual steam cleaning, a cracked insulator or excess gap each suggests a different next test.","A new plug may temporarily change how the engine runs without explaining why the old one fouled. Photographing the deposit preserves evidence for injector or mechanical diagnosis after reassembly."]},{heading:"Two bulletins have different code boundaries",paragraphs:["Bulletin 18-104-15 includes P0301 among several diagnostic improvements for the specified 2012 RT 3.6L/DG2 combination. Verify build configuration and current PCM calibration before considering it.","The X56 bulletin instead names P0300, P0302, P0304 and P0306 and directs leakage testing of even cylinders. P0301 alone must not be converted into an automatic left-head replacement; mechanical testing must prove any cylinder fault."]}],sources:[town2012Flash,pentastarHead,service,mopar]}),
 make(town,{code:"P0340",slug:"chrysler/town-and-country/p0340",title:"P0340 Code Chrysler Town & Country: Cam Circuit Diagnosis",description:"Diagnose Town & Country P0340 using engine-correct sensor location, loaded wiring tests and cam/crank waveform evidence.",definition:"Camshaft Position Sensor Circuit",kind:"cam",quickAnswer:"P0340 means the PCM lost or rejected its expected cam-position signal; it does not prove a failed cam sensor. Identify the circuit for the exact 3.3L, 3.8L or 3.6L engine, inspect harness routing and connectors, load-test power, ground and signal, and scope cam against crank. Signal dropout favors wiring, connector or sensor faults; a clean but shifted relationship plus P0016 supports mechanical timing or reluctor inspection.",yearNotes:["The 3.6L Pentastar has a different multi-cam arrangement from 3.3L/3.8L engines.","Transverse engine packaging changes connector access and heat exposure.","P0335 or multiple sensor codes can reveal shared supply or harness faults.","Repeated stalling, extended crank or timing noise warrants prompt diagnosis."],deepDive:[{heading:"Exact engine identification prevents the wrong test",paragraphs:["Decode the VIN and use the correct schematic before unplugging anything. Earlier pushrod V6 engines and the Pentastar do not use the same cam sensing strategy, connector count or expected waveform.","Inspect areas disturbed during intake, valve-cover or transmission work and where the transverse-engine harness bends near brackets. A connector can look seated while a terminal has backed out or lost grip."]},{heading:"Test voltage while the circuit is working",paragraphs:["Load-test reference and ground and capture the signal during crank and idle. Static continuity can pass through a high-resistance wire that cannot support the sensor under heat or vibration.","When several sensors share a supply and set codes together, isolate branches systematically. Replacing each sensor will not repair a common short, rubbed loom or poor PCM ground."]},{heading:"Cam/crank scope data separates two repair paths",paragraphs:["Intermittent missing edges, noise or low amplitude indicate a signal-generation or circuit issue. Recreate the temperature and vibration recorded in freeze-frame data so an intermittent failure is not missed.","Clean waveforms with a stable phase offset point toward chain indexing, phaser or reluctor position on the applicable engine. That relationship—rather than the word “cam” in P0340—justifies mechanical inspection."]}]}),
 make(town,{code:"P0016",slug:"chrysler/town-and-country/p0016",title:"P0016 Code Chrysler Town & Country: Correlation Diagnosis",description:"Diagnose Town & Country P0016 with exact engine definitions, oil checks, desired/actual cam data and simultaneous cam/crank scope testing.",definition:"Crankshaft–Camshaft Correlation (Bank 1 Sensor A)",kind:"correlation",quickAnswer:"P0016 means the observed Bank 1 Sensor A cam relationship did not match crank position. Confirm what Sensor A means for the exact engine, preserve desired/actual cam data, resolve P0340/P0335 signal codes, verify oil and scope cam against crank. A dropout suggests an electrical or sensor branch; a consistent offset or startup rattle raises mechanical timing, phaser or reluctor priority. Older 3.3L/3.8L and 3.6L Pentastar procedures are not interchangeable.",yearNotes:["Bank 1 Sensor A must be identified from exact engine service information.","Pentastar variable-cam diagnosis differs from earlier pushrod V6 engines.","Oil grade, level and filter condition affect Pentastar phaser response.","Persistent timing noise, stalling or severe misfire requires limiting operation."],deepDive:[{heading:"First decide whether the signal disappeared or moved",paragraphs:["Capture cam and crank on the same time base during crank, idle and the fault condition. Missing edges or noise support sensor, connector, air-gap or harness investigation, while a repeatable phase displacement supports mechanical timing.","Resolve P0340, P0335 and shared-voltage codes before treating correlation as a chain verdict. The PCM cannot judge phase correctly when one of the two signals is unreliable."]},{heading:"Pentastar oil control belongs in the test plan",paragraphs:["For the 3.6L, verify level, viscosity, filter and oil condition, then compare desired and actual cam angle where scan data supports it. Sludge, restricted control passages or a sticking phaser can delay response without a broken chain.","Do not use thicker oil to hide startup noise. If pressure is questionable or rattle persists, stop unnecessary running and follow the engine-specific phaser, tensioner and mechanical-timing procedure."]},{heading:"Older vans need their own reference pattern",paragraphs:["A 3.3L or 3.8L Town & Country does not inherit Pentastar bank, sensor or phaser descriptions. Match the waveform and mechanical timing marks to the VIN-decoded engine before disassembly.","After the measured fault is repaired, perform required relearns and verify synchronization hot and cold. A code that has merely been cleared has not yet passed the correlation monitor."]}]}),
];
